INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Decentralised Peppol 4-corner', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Access Point requirements, penalty enforcement, and the 2028 e-reporting build-out continue to evolve — confirm current requirements directly with FPS Finance or your chosen Peppol Access Point before building an integration.', 'Belgium built its B2B mandate directly on top of infrastructure it had already spent years rolling out for the public sector — B2G e-invoicing arrived first, in stages, before B2B arrived all at once.', 'Belgium leans almost entirely on the existing Peppol ecosystem rather than inventing a national format from scratch.', 'There''s no Belgian government clearance platform for B2B invoices — Mercurius handles B2G only. B2B traffic moves peer-to-peer over Peppol.', 'There''s no separate "e-invoicing account" to open with FPS Finance — registration happens through a commercial Access Point, using your existing enterprise number.', 'Belgium''s penalty ladder is progressive and applies per infringement — not per invoice — which keeps it manageable if you fix the underlying issue quickly.' FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '4-corner', 'Peppol model');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Belgium';
