INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '€1.5k→5k', 'Progressive fines');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2028', 'E-reporting go-live');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Default format", "Peppol BIS Billing 3.0 (UBL 2.1)"], ["European semantic model", "EN 16931"], ["National CIUS", "None — uses Peppol BIS CIUS directly"], ["Alternative syntax", "UN/CEFACT CII D16B (by bilateral agreement)"]]', 'Belgium is one of the few EU markets that hasn''t layered its own national CIUS on top of Peppol BIS — using the standard European profile as-is is fully compliant, which keeps cross-border trade simple.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Business identifiers', '[["Preferred scheme", "0208 (KBO/BCE enterprise number)"], ["Alternative scheme", "9925 (Belgian VAT number, BE + 10 digits)"], ["Directory lookup", "KBO Public Search + Peppol Directory"]]', 'Scheme 9925 is a Peppol "extended value" rather than an official ISO 6523 code — it''s valid for network routing but has more limited support than 0208. If you have a KBO number (almost every registered business does, including foreign companies trading in Belgium), use 0208.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory invoice fields', '[["Header", "Unique invoice number, ISO 8601 issue date, currency, PO reference"], ["Party data", "Legal name, VAT no., KBO/BCE, address, Peppol Participant ID"], ["Line level", "VAT category code (S/Z/E), rate, quantity, unit price, line total"]]', 'Duplicate invoice numbers and mismatched line-level VAT categorisation are the two most common causes of Access Point validation failure — both are checked automatically before the invoice ever reaches the network.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Archiving', '[["Retention period", "7 years minimum"], ["What to keep", "Original XML + Access Point processing logs"]]', 'If you switch Access Point providers, download your original XML files and processing logs before closing your old account — you may lose portal access to historical invoices once you leave, and you''re the one who needs them for a future audit.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Network model', '[["B2B model", "Peppol 4-corner (decentralised)"], ["B2G model", "Mercurius (central hub, Peppol-aligned)"], ["Government authority", "FPS Finance"]]', 'Don''t confuse the two: Mercurius is specifically for invoicing public bodies. Ordinary B2B invoices travel directly between businesses'' Access Points and never touch Mercurius at all.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Access Point connectivity', '[["Requirement", "Certified Peppol Access Point"], ["Common providers", "Many ERPs ship built-in support (Exact, Yuki, Billit, Teamleader, Octopus, and others)"], ["Validation point", "Schematron checks run at the Access Point before network entry"]]', 'One enterprise number can only be linked to one Access Point at a time. To switch providers, your old Access Point must first "unpublish" your KBO number from the directory before your new provider can register it.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Alternative channels', '[["EDI (e.g. EDIFACT)", "Permitted only by mutual agreement"], ["Condition", "Must still be EN 16931-compliant"]]', 'In practice almost everyone defaults to Peppol BIS Billing 3.0, since it needs no bilateral agreement between trading partners — any two Peppol-connected businesses can exchange invoices automatically.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 3 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Coming in 2028', '[["Model", "Peppol 5-corner (adds a reporting leg to the tax authority)"], ["Purpose", "Near-real-time VAT reporting"]]', 'The 5-corner model builds directly on the 4-corner network already in place — if your Access Point integration is solid today, the 2028 upgrade should mostly be your provider''s problem, not yours.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🏛️ B2G stays separate', NULL, NULL, 'If you supply Belgian public bodies, that obligation runs through Mercurius and has applied since 2019 (suppliers) — it doesn''t disappear just because the B2B mandate has arrived alongside it.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🪪 Narrow exemptions', NULL, NULL, 'A handful of specific VAT statuses and transaction types fall outside the domestic B2B scope — if in doubt, the deciding factors are always whether supplier, customer, and transaction are all domestic Belgian B2B.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📶 Network stability', NULL, NULL, 'Early post-mandate reviews found the Peppol network itself performing reliably — most real-world issues traced back to registration gaps or poor data quality at individual businesses, not the infrastructure.');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'First offence', '€1,500', NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Second offence', '€3,000', NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Third offence (within 3 months)', '€5,000', NULL);
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your KBO/BCE enterprise number', 'Check the KBO Public Search if you''re unsure of your number — nearly all VAT-registered entities operating in Belgium have one, including foreign companies with a Belgian establishment.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose a certified Peppol Access Point', 'Pick a standalone provider or confirm your existing accounting/ERP software already includes Peppol connectivity — many mainstream Belgian platforms do.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Let your Access Point verify and publish your ID', 'Your provider verifies your business details and publishes your Peppol Participant ID (scheme 0208 + KBO number) to the global Peppol Directory, making you discoverable to any trading partner.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Test invoice generation against BIS Billing 3.0', 'Validate that your ERP produces correctly structured UBL XML — unique invoice numbers, correct line-level VAT category codes, and complete party identification. Most Access Points offer a sandbox for this.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm inbound receiving works automatically', 'The mandate requires you to receive structured invoices, not just send them — make sure inbound Peppol documents flow into your accounting system without manual handling.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up compliant, tamper-evident archiving', 'Confirm your retention solution meets the 7-year statutory minimum with genuine audit-grade integrity — not just file storage, but demonstrable protection against alteration.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium', 0 FROM countries WHERE name_en = 'Belgium';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'EU Digital Building Blocks — Belgium');
